const SPRITE_ROOT_ID = 'flux-file-type-sprite-root';

let mounted = false;

/** 把 sprite 注入文档一次。Node（SSR/测试）环境下无 document，直接跳过。 */
export function mountFileTypeSprite(): void {
  if (mounted || typeof document === 'undefined' || !document.body) return;
  if (document.getElementById(SPRITE_ROOT_ID)) {
    mounted = true;
    return;
  }
  const root = document.createElement('div');
  root.id = SPRITE_ROOT_ID;
  root.setAttribute('aria-hidden', 'true');
  root.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden';
  root.innerHTML = FILE_TYPE_SPRITE;
  document.body.appendChild(root);
  mounted = true;
}

