const KNOWN_ICONS = new Set([...Object.values(FILE_NAME_ICONS), ...Object.values(EXTENSION_ICONS), 'document']);

/** 解析文件路径对应的 sprite symbol id。 */
export function resolveFileTypeIcon(filePath: string): string {
  const normalized = filePath.replace(/\\/g, '/');
  const fileName = (normalized.split('/').pop() || '').toLowerCase();

  if (FILE_NAME_ICONS[fileName]) return FILE_NAME_ICONS[fileName];
  if (fileName.startsWith('.env')) return 'settings';

  const dot = fileName.lastIndexOf('.');
  if (dot > 0) {
    const ext = fileName.slice(dot + 1);
    const icon = EXTENSION_ICONS[ext];
    if (icon && KNOWN_ICONS.has(icon)) return icon;
    if (KNOWN_ICONS.has(ext)) return ext;
  }
  return 'document';
}

/** 输出可直接插入 HTML 的图标（sprite 未挂载时也不会崩，只是暂时不显示）。 */
export function renderFileTypeIcon(filePath: string, className = 'md-file__icon'): string {
  const id = resolveFileTypeIcon(filePath);
  return '<span class="' + className + '" data-icon="' + id + '"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><use href="#' + id + '"></use></svg></span>';
}
